#include <stdio.h>
#include <stdlib.h>

int main(void) {
    FILE *f = fopen("pets.txt", "r");
    if (!f) {
        perror("fopen() failed");
        exit(EXIT_FAILURE);
    }
    int c;                       // int, not char: it must be able to hold EOF
    int count = 0;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\n') {
            printf("<NL>\n");
        }
        else {
            putchar(c);
        }
        count++;
    }
    if (ferror(f)) {
        fprintf(stderr, "I/O error\n");
    }
    else if (feof(f)) {
        printf("end of file after %d characters\n", count);
    }
    fclose(f);
    printf("EOF is %d\n", EOF);
    return 0;
}

