#include <stdio.h>
#include <stdlib.h>

int main(void) {
    // step 1: write a small data file with fprintf
    FILE *out = fopen("marks.txt", "w");
    if (!out) {
        perror("fopen() failed");
        exit(EXIT_FAILURE);
    }
    fprintf(out, "%s %d\n", "alice", 81);
    fprintf(out, "%s %d\n", "bob", 67);
    fprintf(out, "%s %d\n", "chen", 90);
    fclose(out);

    // step 2: read it back with fscanf
    FILE *in = fopen("marks.txt", "r");
    if (!in) {
        perror("fopen() failed");
        exit(EXIT_FAILURE);
    }
    char name[20];
    int mark;
    int count = 0;
    int total = 0;
    while (fscanf(in, "%19s %d", name, &mark) == 2) {
        printf("%-6s %3d\n", name, mark);
        count++;
        total += mark;
    }
    fclose(in);
    if (count > 0) {
        printf("average = %.2f\n", (double) total / count);
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// writes text into the file name, then reads ints from it with fscanf
void scan_all(const char *name, const char *text) {
    FILE *f = fopen(name, "w");
    if (!f) {
        perror("fopen() failed");
        exit(EXIT_FAILURE);
    }
    fputs(text, f);
    fclose(f);

    f = fopen(name, "r");
    if (!f) {
        perror("fopen() failed");
        exit(EXIT_FAILURE);
    }
    int x;
    int n;
    while ((n = fscanf(f, "%d", &x)) == 1) {
        printf("read %d\n", x);
    }
    printf("fscanf returned %d\n", n);
    fclose(f);
}

int main(void) {
    scan_all("good.txt", "10 20\n30\n");
    scan_all("bad.txt", "10 20\nabc 30\n");
    return 0;
}

