#include <stdio.h>
#include <stdlib.h>

// Returns the number of lines in the file, or -1 if it cannot be opened.
// A last line without a '\n' still counts as a line.
int count_lines(const char *filename) {
    FILE *f = fopen(filename, "r");
    if (f == NULL) {
        return -1;
    }
    int lines = 0;
    int prev = '\n';              // pretend the file starts after a newline
    int c;
    while ((c = fgetc(f)) != EOF) {
        if (c == '\n') {
            lines++;
        }
        prev = c;
    }
    if (prev != '\n') {           // last line had no newline
        lines++;
    }
    fclose(f);
    return lines;
}

int main(void) {
    FILE *f = fopen("three.txt", "w");
    if (!f) {
        perror("fopen() failed");
        exit(EXIT_FAILURE);
    }
    fputs("one\ntwo\nthree", f);  // no newline at the very end
    fclose(f);

    printf("three.txt: %d\n", count_lines("three.txt"));
    printf("missing.txt: %d\n", count_lines("missing.txt"));
    return 0;
}

