#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Copies the longest line of the file (without its '\n') into longest and
// returns its line number (the first one if several tie). Returns 0 for an
// empty file and -1 if the file cannot be opened. Lines are shorter than 99 chars.
int longest_line(const char *filename, char longest[static 100]) {
    FILE *f = fopen(filename, "r");
    if (!f) {
        return -1;
    }
    char buf[100];
    int line = 0;
    int best_line = 0;
    size_t best_len = 0;
    longest[0] = '\0';
    while (fgets(buf, 100, f) != NULL) {
        line++;
        size_t len = strlen(buf);
        if (len > 0 && buf[len - 1] == '\n') {
            buf[len - 1] = '\0';
            len--;
        }
        if (best_line == 0 || len > best_len) {
            best_len = len;
            best_line = line;
            strcpy(longest, buf);
        }
    }
    fclose(f);
    return best_line;
}

#include <stdio.h>
#include <stdlib.h>

int read_ints(const char *filename, int a[static 50]) {
    FILE *f = fopen(filename, "r");
    if (f == NULL) {
        perror(filename);
        exit(EXIT_FAILURE);
    }
    int count = 0;
    int x;
    while (fscanf(f, "%d", &x) == 1) {
        if (count < 50) {
            a[count] = x;
        }
        count++;
    }
    fclose(f);
    return count;
}
